            writer.WriteSingle(value.BoundsCenterZ);
            writer.WriteSingle(value.BoundsSizeX);
            writer.WriteSingle(value.BoundsSizeY);
            writer.WriteSingle(value.BoundsSizeZ);
            writer.WriteString(value.ExamineText);
            writer.WriteByte((byte)value.MenuOptions.Length);
            foreach (var item in value.MenuOptions)
            {
                WriteWorldActorMenuOption(ref writer, item);
            }
        }

        private static int SizeOfWorldActorSpawn(RealtimeWorldActorSpawn value)
        {
            var size = 84;
            size += StringSize(value.ActorDefinitionId);
            size += StringSize(value.SpawnDefinitionId);
            size += StringSize(value.DisplayName);
            size += StringSize(value.FactionId);
            size += StringSize(value.PresentationArchetypeId);
            size += StringSize(value.ExamineText);
            size += 1;
            foreach (var item in value.MenuOptions)
            {
                size += SizeOfWorldActorMenuOption(item);
            }

            return size;
        }

        private static bool TryReadWorldActorSpawn(ref PacketReader reader, out RealtimeWorldActorSpawn value, out string error)
        {
            value = null;
            if (!reader.TryReadUInt64(out var entityId, out error))
            {
                return false;
            }

            if (!reader.TryReadGuid(out var runtimeActorId, out error))
            {
                return false;
            }

            if (!reader.TryReadString(MaximumIdentifierLength, out var actorDefinitionId, out error))
            {
                return false;
            }

            if (!reader.TryReadString(MaximumIdentifierLength, out var spawnDefinitionId, out error))
            {
                return false;
            }

            if (!reader.TryReadString(MaximumNameLength, out var displayName, out error))
            {
                return false;
            }

            if (!reader.TryReadByte(out var kindByte, out error))
            {
                return false;
            }

            var kind = (RealtimeWorldActorKind)kindByte;

            if (!reader.TryReadString(MaximumIdentifierLength, out var factionId, out error))
            {
                return false;
            }

            if (!reader.TryReadByte(out var dispositionByte, out error))
            {
                return false;
            }

            var disposition = (RealtimeWorldActorDisposition)dispositionByte;

            if (!reader.TryReadString(MaximumIdentifierLength, out var presentationArchetypeId, out error))
            {
                return false;
            }

            if (!reader.TryReadInt64(out var stateRevision, out error))
            {
                return false;
            }

            if (!reader.TryReadInt64(out var interactionRevision, out error))
            {
                return false;
            }

            if (!reader.TryReadBoolean(out var isActive, out error))
            {
                return false;
            }

            if (!reader.TryReadSingle(out var positionX, out error))
            {
                return false;
            }

            if (!reader.TryReadSingle(out var positionY, out error))
            {
                return false;
            }

            if (!reader.TryReadSingle(out var positionZ, out error))
            {
                return false;
            }

            if (!reader.TryReadSingle(out var yawDegrees, out error))
            {
                return false;
            }

            if (!reader.TryReadByte(out var activityTierByte, out error))
            {
                return false;
            }

            var activityTier = (RealtimeWorldActorActivityTier)activityTierByte;

            if (!reader.TryReadSingle(out var boundsCenterX, out error))
            {
                return false;
            }

            if (!reader.TryReadSingle(out var boundsCenterY, out error))
            {
                return false;
            }

            if (!reader.TryReadSingle(out var boundsCenterZ, out error))
            {
                return false;
            }

            if (!reader.TryReadSingle(out var boundsSizeX, out error))
            {
                return false;
            }

            if (!reader.TryReadSingle(out var boundsSizeY, out error))
            {
                return false;
            }

            if (!reader.TryReadSingle(out var boundsSizeZ, out error))
            {
                return false;
            }

            if (!reader.TryReadString(MaximumWorldActorExamineTextLength, out var examineText, out error))
            {
                return false;
            }

            if (!reader.TryReadByte(out var menuOptionsCount, out error))
            {
                return false;
            }

            if (menuOptionsCount > MaximumWorldActorCapabilities)
            {
                error = "World actor spawn menu options count is invalid.";
                return false;
            }

            var menuOptions = new RealtimeWorldActorMenuOption[menuOptionsCount];
            for (var index = 0; index < menuOptions.Length; index++)
            {
                if (!TryReadWorldActorMenuOption(ref reader, out var element, out error))
                {
                    return false;
                }

                menuOptions[index] = element;
            }

            value = new RealtimeWorldActorSpawn(entityId, runtimeActorId, actorDefinitionId, spawnDefinitionId, displayName, kind, factionId, disposition, presentationArchetypeId, stateRevision, interactionRevision, isActive, positionX, positionY, positionZ, yawDegrees, activityTier, boundsCenterX, boundsCenterY, boundsCenterZ, boundsSizeX, boundsSizeY, boundsSizeZ, examineText, menuOptions);
            return true;
        }

        private static bool IsValidWorldActorSpawn(RealtimeWorldActorSpawn value)
        {
            if (value == null
                || value.EntityId < 1
                || value.RuntimeActorId == Guid.Empty
                || string.IsNullOrWhiteSpace(value.ActorDefinitionId)
                || value.ActorDefinitionId.Length > MaximumIdentifierLength
                || string.IsNullOrWhiteSpace(value.SpawnDefinitionId)
                || value.SpawnDefinitionId.Length > MaximumIdentifierLength
                || string.IsNullOrWhiteSpace(value.DisplayName)
                || value.DisplayName.Length > MaximumNameLength
                || !IsDefined(value.Kind)
                || string.IsNullOrWhiteSpace(value.FactionId)
                || value.FactionId.Length > MaximumIdentifierLength
                || !IsDefined(value.Disposition)
                || string.IsNullOrWhiteSpace(value.PresentationArchetypeId)
                || value.PresentationArchetypeId.Length > MaximumIdentifierLength
                || value.StateRevision < 1
                || value.InteractionRevision < 1
                || !IsFinite(value.PositionX)
                || !IsFinite(value.PositionY)
                || !IsFinite(value.PositionZ)
                || !IsFinite(value.YawDegrees)
                || !IsDefined(value.ActivityTier)
                || !IsFinite(value.BoundsCenterX)
                || !IsFinite(value.BoundsCenterY)
                || !IsFinite(value.BoundsCenterZ)
                || !IsFinite(value.BoundsSizeX)
                || value.BoundsSizeX <= 0f
                || !IsFinite(value.BoundsSizeY)
                || value.BoundsSizeY <= 0f
                || !IsFinite(value.BoundsSizeZ)
                || value.BoundsSizeZ <= 0f
                || string.IsNullOrWhiteSpace(value.ExamineText)
                || value.ExamineText.Length > MaximumWorldActorExamineTextLength
                || value.MenuOptions == null
                || value.MenuOptions.Length > MaximumWorldActorCapabilities)
            {
                return false;
            }

            foreach (var item in value.MenuOptions)
            {
                if (!IsValidWorldActorMenuOption(item))
                {
                    return false;
                }
            }

            for (var first = 0; first < value.MenuOptions.Length; first++)
            {
                for (var second = first + 1; second < value.MenuOptions.Length; second++)
                {
                    if (value.MenuOptions[first].CapabilityId == value.MenuOptions[second].CapabilityId)
                    {
                        return false;
                    }
                }
            }

            return true;
        }

