            {
                case RealtimeWorldInteractionOperationKind.Open:
                {
                    break;
                }
                case RealtimeWorldInteractionOperationKind.Close:
                {
                    break;
                }
                case RealtimeWorldInteractionOperationKind.CapabilityAction:
                {
                    size += 74;
                    size += StringSize(value.CapabilityId);
                    size += StringSize(value.OfferDefinitionId);
                    break;
                }
                default:
                {
                    throw new ArgumentException("World interaction intent is invalid.", nameof(value));
                }
            }

            return size;
        }

        private static bool TryReadWorldInteractionIntent(ref PacketReader reader, out RealtimeWorldInteractionIntent value, out string error)
        {
            value = null;
            if (!reader.TryReadGuid(out var operationId, out error))
            {
                return false;
            }

            if (!reader.TryReadGuid(out var simulationSessionId, out error))
            {
                return false;
            }

            if (!reader.TryReadGuid(out var interactionSessionId, out error))
            {
                return false;
            }

            if (!reader.TryReadByte(out var operationKindByte, out error))
            {
                return false;
            }

            var operationKind = (RealtimeWorldInteractionOperationKind)operationKindByte;

            if (!reader.TryReadByte(out var targetKindByte, out error))
            {
                return false;
            }

            var targetKind = (RealtimeWorldInteractionTargetKind)targetKindByte;

            if (!reader.TryReadUInt64(out var targetEntityId, out error))
            {
                return false;
            }

            if (!reader.TryReadGuid(out var targetRuntimeId, out error))
            {
                return false;
            }

            if (!reader.TryReadInt64(out var expectedTargetRevision, out error))
            {
                return false;
            }

            string capabilityId = string.Empty;
            RealtimeWorldActorCapabilityKind capabilityKind = default;
            long expectedCapabilityRevision = 0;
            RealtimeCapabilityActionKind capabilityAction = default;
            long expectedCharacterRevision = 0;
            Guid itemInstanceId = Guid.Empty;
            long expectedItemRevision = 0;
            Guid destinationContainerId = Guid.Empty;
            int destinationSlotIndex = -1;
            string offerDefinitionId = string.Empty;
            int quantity = 0;
            long expectedPrice = 0;

            switch (operationKind)
            {
                case RealtimeWorldInteractionOperationKind.Open:
                {
                    interactionSessionId = Guid.Empty;
                    break;
                }
                case RealtimeWorldInteractionOperationKind.Close:
                {
                    break;
                }
                case RealtimeWorldInteractionOperationKind.CapabilityAction:
                {
                    if (!reader.TryReadString(MaximumWorldActorCapabilityIdLength, out capabilityId, out error))
                    {
                        return false;
                    }

                    if (!reader.TryReadByte(out var capabilityKindByte, out error))
                    {
                        return false;
                    }

                    capabilityKind = (RealtimeWorldActorCapabilityKind)capabilityKindByte;

                    if (!reader.TryReadInt64(out expectedCapabilityRevision, out error))
                    {
                        return false;
                    }

                    if (!reader.TryReadByte(out var capabilityActionByte, out error))
                    {
                        return false;
                    }

                    capabilityAction = (RealtimeCapabilityActionKind)capabilityActionByte;

                    if (!reader.TryReadInt64(out expectedCharacterRevision, out error))
                    {
                        return false;
                    }

                    if (!reader.TryReadGuid(out itemInstanceId, out error))
                    {
                        return false;
                    }

                    if (!reader.TryReadInt64(out expectedItemRevision, out error))
                    {
                        return false;
                    }

                    if (!reader.TryReadGuid(out destinationContainerId, out error))
                    {
                        return false;
                    }

                    if (!reader.TryReadInt32(out destinationSlotIndex, out error))
                    {
                        return false;
                    }

                    if (!reader.TryReadString(MaximumDefinitionIdLength, out offerDefinitionId, out error, allowBlank: true))
                    {
                        return false;
                    }

                    if (!reader.TryReadInt32(out quantity, out error))
                    {
                        return false;
                    }

                    if (!reader.TryReadInt64(out expectedPrice, out error))
                    {
                        return false;
                    }

                    break;
                }
                default:
                {
                    error = "World interaction intent operation kind is invalid.";
                    return false;
                }
            }

            value = new RealtimeWorldInteractionIntent(operationId, simulationSessionId, interactionSessionId, operationKind, targetKind, targetEntityId, targetRuntimeId, expectedTargetRevision, capabilityId, capabilityKind, expectedCapabilityRevision, capabilityAction, expectedCharacterRevision, itemInstanceId, expectedItemRevision, destinationContainerId, destinationSlotIndex, offerDefinitionId, quantity, expectedPrice);
            return true;
        }

        private static bool IsValidWorldInteractionIntent(RealtimeWorldInteractionIntent value)
        {
            if (value == null
                || value.OperationId == Guid.Empty
                || value.SimulationSessionId == Guid.Empty
                || !IsDefined(value.OperationKind)
                || !IsDefined(value.TargetKind)
                || value.TargetEntityId < 1
                || value.TargetRuntimeId == Guid.Empty
                || value.ExpectedTargetRevision < 1)
            {
                return false;
            }

            switch (value.OperationKind)
            {
                case RealtimeWorldInteractionOperationKind.Open:
                {
                    if (value.InteractionSessionId != Guid.Empty)
                    {
                        return false;
                    }

                    break;
                }
                case RealtimeWorldInteractionOperationKind.Close:
                {
                    if (value.InteractionSessionId == Guid.Empty)
                    {
                        return false;
                    }

                    break;
                }
                case RealtimeWorldInteractionOperationKind.CapabilityAction:
                {
                    if (value.InteractionSessionId == Guid.Empty
                        || string.IsNullOrWhiteSpace(value.CapabilityId)
                        || value.CapabilityId.Length > MaximumWorldActorCapabilityIdLength
                        || !IsDefined(value.CapabilityKind)
                        || value.ExpectedCapabilityRevision < 1
                        || !IsDefined(value.CapabilityAction)
                        || value.OfferDefinitionId == null
                        || value.OfferDefinitionId.Length > MaximumDefinitionIdLength)
                    {
                        return false;
                    }

                    break;
                }
                default:
                {
                    return false;
                }
            }

            return SatisfiesRules(value);
        }

